arguments.command:
python3 -I - <<'EOF'
import json
rec=json.loads(open('observed_run/experiment_logs/rollout_records.jsonl').readline())
m=rec['tito_session_mismatch']
def walk(x,d=0):
    if isinstance(x,dict):
        for k,v in x.items():
            if isinstance(v,(dict,list)): print('  '*d+k+':'); walk(v,d+1)
            else:
                s=str(v)
                print('  '*d+f'{k}: {s[:300]}')
    elif isinstance(x,list):
        print('  '*d+f'list len {len(x)}')
        walk(x[0],d+1)
walk(m)
EOF

